'use strict';
/**
 * 排盘计算服务 · HTTP 编排层
 * ============================================================
 * 架构（用户当面纠正过一次，写在这里防止再走回头路）：
 *
 *   [前端 聊天UI / 报告页]
 *          │  HTTP，只传出生信息与问题
 *          ▼
 *   [本服务 = 编排层]  ← 你在这里
 *          │  调用
 *          ▼
 *   [计算层 lib/]  确定性：历法、天文、安星、取象
 *
 *   前端【只消费事实层 JSON】，不参与任何历法/天文计算。
 *   把 787KB 排盘引擎塞进浏览器是错的：不是做不到，
 *   而是那会让"唯一事实来源"消失 —— 前后端算法版本一旦不一致，
 *   同一个人会拿到两张不同的盘。
 *
 * 零外部依赖：只用 Node 内置 http / fs。
 *   计算依赖（lunar-javascript / iztro）在 lib 层。
 */

const http = require('http');
const fs = require('fs');
const path = require('path');
const { buildFact } = require('./lib/fact.js');
const { CITIES, BY_NAME } = require('./lib/cities.js');

const PORT = process.env.PORT || 3007;
const PUBLIC_DIR = path.join(__dirname, 'public');

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'application/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
};

function sendJSON(res, code, obj) {
  const body = JSON.stringify(obj, null, 2);
  res.writeHead(code, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(body),
    'Access-Control-Allow-Origin': '*',
  });
  res.end(body);
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    req.on('data', (c) => {
      data += c;
      if (data.length > 1e6) { reject(new Error('请求体过大')); req.destroy(); }
    });
    req.on('end', () => {
      if (!data) return resolve({});
      try { resolve(JSON.parse(data)); } catch (e) { reject(new Error('JSON 解析失败: ' + e.message)); }
    });
    req.on('error', reject);
  });
}

/** 输入校验：宁可明确报错，也不要用默认值悄悄算出一张错的盘 */
function validate(input) {
  const errs = [];
  const num = (v, name, min, max) => {
    const n = Number(v);
    if (!Number.isFinite(n)) { errs.push(`${name} 必须是数字`); return null; }
    if (n < min || n > max) { errs.push(`${name} 应在 ${min}–${max} 之间，收到 ${n}`); return null; }
    return n;
  };

  const y = num(input.y, '出生年', 1901, 2099);
  const m = num(input.m, '出生月', 1, 12);
  const d = num(input.d, '出生日', 1, 31);
  const h = num(input.h, '出生时', 0, 23);
  const mi = num(input.mi ?? 0, '出生分', 0, 59);

  if (input.gender && !['男', '女'].includes(input.gender)) errs.push('性别须为「男」或「女」');

  // 日期真实性检查（2月30日之类）
  if (y && m && d) {
    const dt = new Date(Date.UTC(y, m - 1, d));
    if (dt.getUTCMonth() + 1 !== m || dt.getUTCDate() !== d) errs.push(`${y}年${m}月没有${d}日`);
  }

  let lon = input.lonEast, lat = input.lat;
  if (input.city) {
    const c = BY_NAME[input.city];
    if (c) { lon = c.lon; lat = c.lat; }
    else errs.push(`未收录城市「${input.city}」，请改用经纬度输入`);
  }
  if (lon == null || lat == null) {
    errs.push('需要提供城市，或直接给出经纬度（lonEast / lat）');
  } else {
    const LON = num(lon, '经度', -180, 180);
    const LAT = num(lat, '纬度', -66, 66);
    lon = LON; lat = LAT;
  }

  if (input.basis && !['solar', 'clock'].includes(input.basis)) errs.push('时间基准须为 solar 或 clock');

  return {
    errors: errs,
    value: { y, m, d, h, mi, gender: input.gender || '男', city: input.city || null, lonEast: lon, lat, basis: input.basis },
  };
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const p = url.pathname;

  // ── CORS 预检 ──
  if (req.method === 'OPTIONS') {
    res.writeHead(204, {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET,POST,OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type',
    });
    return res.end();
  }

  // ── 健康检查 ──
  if (p === '/api/health') {
    return sendJSON(res, 200, {
      ok: true,
      service: 'mingli-agent 排盘计算服务',
      version: '1.0.0',
      schema: 'mingli.fact/1',
      endpoints: {
        'POST /api/chart': '排盘，返回事实层 JSON（八字 + 紫微 + 占星 + 印证）',
        'GET  /api/cities': '城市经纬度表',
        'GET  /api/dimensions': '印证所用共同维度定义',
      },
    });
  }

  // ── 城市表 ──
  if (p === '/api/cities') return sendJSON(res, 200, { cities: CITIES });

  // ── 维度定义 ──
  if (p === '/api/dimensions') {
    const rules = require('./lib/rules.js');
    return sendJSON(res, 200, { dimensions: rules.DIMENSIONS, validity: rules.VALIDITY });
  }

  // ── 排盘 ──
  if (p === '/api/chart') {
    if (req.method !== 'POST') return sendJSON(res, 405, { error: '请用 POST' });
    let body;
    try { body = await readBody(req); }
    catch (e) { return sendJSON(res, 400, { error: e.message }); }

    const { errors, value } = validate(body);
    if (errors.length) return sendJSON(res, 400, { error: '输入校验未通过', details: errors });

    try {
      const t0 = Date.now();
      const fact = buildFact(value);
      fact.meta = { computeMs: Date.now() - t0, engine: 'mingli-agent/1.0.0' };
      return sendJSON(res, 200, fact);
    } catch (e) {
      console.error('[chart] 排盘失败', e);
      return sendJSON(res, 500, { error: '排盘失败: ' + e.message });
    }
  }

  // ── 静态文件 ──
  if (req.method === 'GET') {
    let file = p === '/' ? '/index.html' : p;
    const full = path.join(PUBLIC_DIR, path.normalize(file).replace(/^(\.\.[/\\])+/, ''));
    if (!full.startsWith(PUBLIC_DIR)) { res.writeHead(403); return res.end('Forbidden'); }
    if (fs.existsSync(full) && fs.statSync(full).isFile()) {
      const ext = path.extname(full);
      res.writeHead(200, { 'Content-Type': MIME[ext] || 'application/octet-stream' });
      return fs.createReadStream(full).pipe(res);
    }
  }

  sendJSON(res, 404, { error: '未找到', path: p });
});

server.listen(PORT, '127.0.0.1', () => {
  console.log('命理师 Agent · 排盘计算服务');
  console.log('  监听 http://127.0.0.1:' + PORT);
  console.log('  排盘  POST http://127.0.0.1:' + PORT + '/api/chart');
  console.log('  城市  GET  http://127.0.0.1:' + PORT + '/api/cities');
  console.log('');
  console.log('  架构：前端只消费事实层 JSON，不做任何历法/天文计算。');
});

