'use strict';
/**
 * 印证引擎回归测试
 * 覆盖：触发率分布、边界出生信息、三体系交叉一致性、相左/印证/孤证的产出。
 */
const B = require('../lib/bazi.js');
const Z = require('../lib/ziwei.js');
const A = require('../lib/astro.js');
const R = require('../lib/rules.js');

let pass = 0, fail = 0;
const t = (name, cond, extra) => {
  if (cond) { pass++; console.log('  ✓ ' + name); }
  else { fail++; console.log('  ✗ ' + name + (extra ? '  → ' + extra : '')); }
};

/* ── 1. 历法层互证（两个独立库）── */
console.log('\n【1】历法层互证：农历日期（lunar-javascript vs iztro）');
{
  let mismatch = 0, n = 0, monthDiff = 0;
  for (let y = 1950; y <= 2020; y += 7) {
    for (const [m, d] of [[1, 1], [3, 15], [6, 30], [9, 9], [12, 31]]) {
      for (const h of [0, 5, 12, 23]) {
        const o = { y, m, d, h, mi: 0, gender: '男', lonEast: 120, lat: 30 };
        const b = B.chart(o), z = Z.chart(o);
        if (b.lunarText !== z.lunarDate) {
          mismatch++;
          if (mismatch <= 3) console.log('    ✗ ' + y + '-' + m + '-' + d + ': 农历[' + b.lunarText + '] vs [' + z.lunarDate + ']');
        }
        if (b.pillars[1].gz !== (z.chineseDate || '').split(' ')[1]) monthDiff++;
        n++;
      }
    }
  }
  t(`农历日期一致（${n} 组）`, mismatch === 0, mismatch + ' 组不一致');
  // 月柱定义不同是【预期】的，不是 bug；只要不是全部不同即可
  t('月柱存在约定差异但非全量（证明是"定义不同"而非"实现错误"）',
    monthDiff > 0 && monthDiff < n, monthDiff + '/' + n);
}

/* ── 2. 占星自检残差 ── */
console.log('\n【2】占星上升点自检（解析式 vs 数值高度，残差应 ≈ 0）');
{
  let worst = 0;
  for (let y = 1900; y <= 2100; y += 10) {
    for (const lat of [0, 23.5, 39.9, 55, -33]) {
      const c = A.chart(y, 6, 15, 4, 116.4, lat);
      worst = Math.max(worst, c.precision.ascendantSelfCheckDeg);
    }
  }
  t('上升点残差 < 0.001°', worst < 0.001, '最差 ' + worst);
}

