{
  const mk = (system, dim, dir, strength) => ({ system, dim, dir, strength, basis: '', citation: '', detail: '' });
  // 两家一致 → converge
  let r = R.verify([mk('八字', 'action', 1, 0.8), mk('占星', 'action', 1, 0.6)]);
  t('两家同向 → 印证', r[0].verdict === 'converge', r[0].verdict);
  t('两家同向 → 标签为「多体系共识」', r[0].agreementLabel === '多体系共识', r[0].agreementLabel);
  t('印证说明中明确否认"更可能为真"', /不构成/.test(r[0].note));

  // 三家一致 → converge
  r = R.verify([mk('八字', 'action', 1, 0.8), mk('占星', 'action', 1, 0.6), mk('紫微', 'action', 1, 0.9)]);
  t('三家同向 → 印证', r[0].verdict === 'converge');
  t('三家同向 → 一致度 1.0', r[0].agreement === 1);

  // 两家相反 → diverge
  r = R.verify([mk('八字', 'action', 1, 0.8), mk('占星', 'action', -1, 0.6)]);
  t('两家反向 → 相左', r[0].verdict === 'diverge', r[0].verdict);
  t('相左 → 标签为「体系分歧」', r[0].agreementLabel === '体系分歧', r[0].agreementLabel);
  t('相左 → 给出追问话术', !!r[0].probe);

  // 绝不出现"可信度"这类无依据宣称
  const allNotes = R.verify([mk('八字', 'action', 1, 0.8), mk('占星', 'action', 1, 0.6),
    mk('八字', 'risk', 1, 0.5), mk('占星', 'risk', -1, 0.5)]).map((d) => d.note).join('');
  t('输出中不含"可信度高"等无依据宣称', !/可信度/.test(allNotes));

  // 同体系两条 → 仍是孤证
  r = R.verify([mk('八字', 'action', 1, 0.8), mk('八字', 'action', 1, 0.5)]);
  t('同一体系两条信号 → 孤证（不算印证）', r[0].verdict === 'single', r[0].verdict);

  // 三家反向混合 → diverge
  r = R.verify([mk('八字', 'action', 1, 0.8), mk('占星', 'action', -1, 0.6), mk('紫微', 'action', 1, 0.9)]);
  t('三家 2:1 分歧 → 相左', r[0].verdict === 'diverge');

  // 无信号
  r = R.verify([]);
  t('无信号 → verdict=none', r.every((d) => d.verdict === 'none'));
}

